describe("loadConfigFrom", () => {
  it("reads keys under the path into env", async () => {
    const env: Record<string, string | undefined> = { LOG_LEVEL: "info" };
    const values = await loadConfigFrom(memory(), {
      path: "services/orders",
      env,
      required: ["DATABASE_URL"],
    });
    expect(values).toEqual({
      DATABASE_URL: "postgres://db",
      LOG_LEVEL: "debug",
      GROW_SECRETS_ADDR: "http://evil",
    });
    expect(env).toEqual({ DATABASE_URL: "postgres://db", LOG_LEVEL: "debug" });
  });

  it("keeps existing variables without override and writes nothing with into none", async () => {
    const env: Record<string, string | undefined> = { LOG_LEVEL: "info" };
    await loadConfigFrom(memory(), { path: "services/orders", env, override: false });
    expect(env["LOG_LEVEL"]).toBe("info");
    const untouched: Record<string, string | undefined> = {};
    await loadConfigFrom(memory(), { path: "services/orders", env: untouched, into: "none" });
    expect(untouched).toEqual({});
  });

  it("reads the provider root and fails naming every missing key", async () => {
    const p = new InMemorySecretsProvider({ initial: { A: "1" } });
    expect(await loadConfigFrom(p, { env: {}, into: "none" })).toEqual({ A: "1" });
    const err = await loadConfigFrom(p, {
      path: "services/orders",
      env: { B: "set" },
      required: ["A", "B", "C"],
    }).catch((e: unknown) => e);
    expect(err).toBeInstanceOf(NotFoundError);
    expect((err as Error).message).toContain("A, C");
    expect((err as Error).message).toContain('"services/orders"');
  });
});

describe("loadConfig", () => {
  it("connects with the bootstrap, loads and closes", async () => {
    let closed = 0;
    let seen: unknown;
    const connect: SecretsConnector = (bootstrap) => {
      seen = bootstrap;
      return Promise.resolve({
        provider: memory(),
        close: () => {
          closed++;
          return Promise.resolve();
        },
      });
    };
    const env: Record<string, string | undefined> = { ...BOOT };
    const values = await loadConfig({ env, connect, required: ["DATABASE_URL"] });
    expect(values["DATABASE_URL"]).toBe("postgres://db");
    expect(env["DATABASE_URL"]).toBe("postgres://db");
    expect(env["GROW_SECRETS_ADDR"]).toBe("http://secrets:8200");
    expect(closed).toBe(1);
    expect(seen).toMatchObject({ path: "services/orders" });
  });

  it("uses the connection path and closes on errors", async () => {
    let closed = 0;
    const connect: SecretsConnector = () =>
      Promise.resolve({
        provider: memory(),
        path: "services/other",
        close: () => {
          closed++;
          return Promise.resolve();
        },
      });
    expect(await loadConfig({ env: { ...BOOT }, connect, into: "none" })).toEqual({ X: "no" });
    await expect(
      loadConfig({ env: { ...BOOT }, connect, required: ["NOPE"] }),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(closed).toBe(2);
  });

  it("checks required keys against the environment without a bootstrap", async () => {
    expect(await loadConfig({ env: { A: "1" }, required: ["A"] })).toEqual({});
    await expect(loadConfig({ env: {}, required: ["A"] })).rejects.toBeInstanceOf(NotFoundError);
    const saved = process.env["GROW_SECRETS_PROVIDER"];
    delete process.env["GROW_SECRETS_PROVIDER"];
    const addr = process.env["GROW_SECRETS_ADDR"];
    delete process.env["GROW_SECRETS_ADDR"];
    try {
      expect(await loadConfig()).toEqual({});
    } finally {
      if (saved !== undefined) process.env["GROW_SECRETS_PROVIDER"] = saved;
      if (addr !== undefined) process.env["GROW_SECRETS_ADDR"] = addr;
    }
  });

  it("only checks required keys when GROW_SECRETS_LOADED is set", async () => {
    const connect: SecretsConnector = () => Promise.reject(new Error("must not connect"));
    const env = { ...BOOT, GROW_SECRETS_LOADED: "1", A: "1" };
    expect(secretsPreloaded(env)).toBe(true);
    expect(secretsPreloaded({ GROW_SECRETS_LOADED: "TRUE" })).toBe(true);
    expect(secretsPreloaded({ GROW_SECRETS_LOADED: "0" })).toBe(false);
    expect(await loadConfig({ env, connect, required: ["A"] })).toEqual({
      A: "1",
    });
    await expect(loadConfig({ env, connect, required: ["B"] })).rejects.toBeInstanceOf(
      NotFoundError,
    );
    expect(await loadConfig({ env, connect })).toEqual({});
  });

  it("rejects a bootstrap for another provider", async () => {
    await expect(
      loadConfig({ env: { GROW_SECRETS_PROVIDER: "something-else" } }),
    ).rejects.toBeInstanceOf(ConfigError);
  });
});
